export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let rollHat = 0, pitchHat = 0, yawHat = 0;
  let rRollHat = 0, rPitchHat = 0, rYawHat = 0;

  // Disturbance acceleration estimates (m/s^2)
  let dx = 0, dy = 0, dz = 0;
  // Motor normalized thrust state estimate
  let mu = 0;
  let kThrust = 21.0; // 16*(1 - w/4)/m nominal
  let dragPerMass = 0.42 / 0.72;

  // Inner loop integral estimate & previous desired angles
  let prevPitchDes = 0, prevRollDes = 0;
  let attBiasRoll = 0, attBiasPitch = 0;
  let yawInt = 0;

  // Navigation state
  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let refX = 0, refY = 0, refZ = 0;
  let prevAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };
  let gustShock = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, a = obs.att, r = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        rollHat = a.roll; pitchHat = a.pitch; yawHat = a.yaw;
        rRollHat = r.roll; rPitchHat = r.pitch; rYawHat = r.yaw;
        refX = p.x; refY = 0.6; refZ = p.z;
      } else {
        // 1. Predict attitude
        rollHat += rRollHat * dt;
        pitchHat += rPitchHat * dt;
        yawHat += rYawHat * dt;
        rollHat += 0.65 * (a.roll - rollHat);
        pitchHat += 0.65 * (a.pitch - pitchHat);
        yawHat += 0.65 * (a.yaw - yawHat);
        rRollHat += 0.50 * (r.roll - rRollHat);
        rPitchHat += 0.50 * (r.pitch - rPitchHat);
        rYawHat += 0.50 * (r.yaw - rYawHat);

        // Estimate attitude tracking bias (from weak motor)
        attBiasRoll = clamp(attBiasRoll + 0.015 * (prevAction.roll - rollHat), -0.12, 0.12);
        attBiasPitch = clamp(attBiasPitch + 0.015 * (prevAction.pitch - pitchHat), -0.12, 0.12);

        // 2. Predict motor thrust state (nominal lag 0.04s)
        mu += (prevAction.thrust - mu) * (1 - Math.exp(-dt / 0.04));

        // 3. Compute thrust direction from measured/filtered attitude
        const bodyX = Math.sin(pitchHat) * Math.cos(rollHat);
        const bodyZ = -Math.sin(rollHat);
        const cy = Math.cos(yawHat), sy = Math.sin(yawHat);
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = Math.cos(pitchHat) * Math.cos(rollHat);
        const dirZ = -sy * bodyX + cy * bodyZ;

        // Vertical thrust acceleration estimate
        const fThrustMag = kThrust * mu;
        const axModel = fThrustMag * dirX - dragPerMass * vx + dx;
        const ayModel = py > 0.075 ? (fThrustMag * dirY - dragPerMass * vy - 9.81 + dy) : 0;
        const azModel = fThrustMag * dirZ - dragPerMass * vz + dz;

        const vxPred = vx + axModel * dt;
        const vyPred = py > 0.075 ? (vy + ayModel * dt) : 0;
        const vzPred = vz + azModel * dt;

        const pxPred = px + vx * dt + 0.5 * axModel * dt * dt;
        const pyPred = py + vy * dt + 0.5 * ayModel * dt * dt;
        const pzPred = pz + vz * dt + 0.5 * azModel * dt * dt;

        const evx = v.x - vxPred;
        const evy = v.y - vyPred;
        const evz = v.z - vzPred;

        // Adaptive disturbance observer gain: fast jump when innovation exceeds noise bound (0.025 m/s)
        const shockX = Math.abs(evx) > 0.024 ? 0.32 : 0.12;
        const shockZ = Math.abs(evz) > 0.024 ? 0.32 : 0.12;
        if (Math.hypot(evx, evz) > 0.030) gustShock = 8;
        else if (gustShock > 0) gustShock--;

        if (py > 0.08) {
          dx = clamp(dx + shockX * (evx / dt), -8.0, 8.0);
          dz = clamp(dz + shockZ * (evz / dt), -8.0, 8.0);
          dy = clamp(dy + 0.10 * (evy / dt), -5.0, 5.0);
          // Slowly adapt kThrust from dy so dy stays near 0
          if (mu > 0.25 && dirY > 0.7) {
            kThrust = clamp(kThrust + 0.04 * dy, 16.5, 27.5);
            dy *= 0.96;
            const estMass = clamp(15.2 / kThrust, 0.60, 0.85);
            dragPerMass = 0.42 / estMass;
          }
        }

        px = pxPred + 0.65 * (p.x - pxPred);
        py = pyPred + 0.65 * (p.y - pyPred);
        pz = pzPred + 0.65 * (p.z - pzPred);

        vx = vxPred + 0.45 * evx + 0.10 * ((p.x - pxPred) / dt);
        vy = vyPred + 0.45 * evy + 0.10 * ((p.y - pyPred) / dt);
        vz = vzPred + 0.45 * evz + 0.10 * ((p.z - pzPred) / dt);
      }

      // 4. Navigation & Waypoint Logic
      let targetX, targetY, targetZ;
      let vxFF = 0, vyFF = 0, vzFF = 0;
      let kpXZ = 5.5, kdXZ = 4.2;
      let kpY = 6.5, kdY = 4.2;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }

        const alignX = gate.x - 0.26;
        if (phase === 'align') {
          targetY = gate.y;
          targetZ = gate.z;
          // Do not let targetX get close to gate plane until y and z are reasonably close
          const yzErr = Math.hypot(py - gate.y, pz - gate.z);
          targetX = yzErr > 0.18 ? Math.min(alignX - 0.08, Math.max(px, alignX - 0.35)) : alignX;

          // Predict position 0.18s ahead
          const zPred = pz + vz * 0.18;
          const yPred = py + vy * 0.18;
          const aligned =
            Math.abs(px - alignX) < 0.11 &&
            Math.abs(py - gate.y) < 0.065 &&
            Math.abs(pz - gate.z) < 0.042 &&
            Math.abs(yPred - gate.y) < 0.075 &&
            Math.abs(zPred - gate.z) < 0.050 &&
            Math.hypot(vx, vy, vz) < 0.35 &&
            gustShock === 0;

          if (aligned) settle++;
          else settle = Math.max(0, settle - 1);

          if (settle >= 6) {
            phase = 'cross';
          }
          kpXZ = 6.0; kdXZ = 4.4;
        }

        if (phase === 'cross') {
          targetX = gate.x + 0.32;
          targetY = gate.y;
          targetZ = gate.z;
          vxFF = 0.95;
          kpXZ = 8.5; kdXZ = 5.0;
          kpY = 8.0; kdY = 4.8;

          // Safety check before crossing gate plane: if a sudden gust pushed predicted crossing outside safe margin
          const distToGate = gate.x - px;
          if (distToGate > 0.04) {
            const tCross = clamp(distToGate / Math.max(0.35, vx), 0.04, 0.35);
            const zAtGate = pz + vz * tCross;
            const yAtGate = py + vy * tCross;
            const stopDist = (vx > 0 ? vx * vx / (2 * 3.8) : 0);
            if ((Math.abs(zAtGate - gate.z) > 0.088 || Math.abs(yAtGate - gate.y) > 0.16) && distToGate > stopDist + 0.03) {
              phase = 'align';
              settle = 0;
              targetX = gate.x - 0.28;
              vxFF = 0;
            }
          }
        }
      } else {
        // Landing on pad
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'pad_approach';
          settle = 0;
        }
        targetX = pad.x;
        targetZ = pad.z;
        const horizErr = Math.hypot(px - pad.x, pz - pad.z);
        const horizSpd = Math.hypot(vx, vz);

        if (phase === 'pad_approach') {
          // Smooth descent slope as we approach pad horizontally
          targetY = clamp(0.18 + 0.75 * horizErr, 0.18, 0.95);
          if (horizErr < 0.085 && horizSpd < 0.22 && py < 0.28) {
            settle++;
            if (settle >= 5) phase = 'descend';
          } else {
            settle = 0;
          }
          kpXZ = 6.0; kdXZ = 4.5;
        }

        if (phase === 'descend') {
          if (horizErr > 0.135) {
            phase = 'pad_approach';
            settle = 0;
            targetY = 0.20;
          } else {
            targetY = 0.05;
            vyFF = py > 0.11 ? -0.22 : -0.08;
            kpXZ = 5.5; kdXZ = 4.2;
          }
          // Touchdown hold mode once on pad
          if (py <= 0.084 && horizErr <= 0.12 && Math.hypot(vx, vy, vz) < 0.38) {
            const rollCmd = clamp(-0.08 * rollHat, -0.10, 0.10);
            const pitchCmd = clamp(-0.08 * pitchHat, -0.10, 0.10);
            prevAction = { thrust: 0.12, roll: rollCmd, pitch: pitchCmd, yawRate: clamp(-1.5 * yawHat, -0.5, 0.5) };
            return prevAction;
          }
        }
      }

      // Smooth reference step for large transitions
      const maxStepXZ = phase === 'cross' ? 0.60 : 0.45;
      const errX = clamp(targetX - px, -maxStepXZ, maxStepXZ);
      const errZ = clamp(targetZ - pz, -maxStepXZ, maxStepXZ);
      const errY = clamp(targetY - py, -0.55, 0.55);

      const axDes = clamp(kpXZ * errX + kdXZ * (vxFF - vx), -4.2, 4.2);
      const azDes = clamp(kpXZ * errZ + kdXZ * (vzFF - vz), -4.2, 4.2);
      const ayDes = clamp(kpY * errY + kdY * (vyFF - vy), -3.8, 4.8);

      // Total required thrust acceleration vector
      const fTx = axDes + dragPerMass * vx - dx;
      const fTz = azDes + dragPerMass * vz - dz;
      const fTy = clamp(9.81 + ayDes + dragPerMass * vy - dy, 2.5, 16.5);

      const cy = Math.cos(yawHat), sy = Math.sin(yawHat);
      const fBodyX = cy * fTx - sy * fTz;
      const fBodyZ = sy * fTx + cy * fTz;

      const pitchDes = clamp(Math.atan2(fBodyX, fTy), -0.50, 0.50);
      const rollDes = clamp(-Math.atan2(fBodyZ, Math.hypot(fBodyX, fTy)), -0.50, 0.50);

      const dPitchDes = clamp((pitchDes - prevPitchDes) / dt, -3.0, 3.0);
      const dRollDes = clamp((rollDes - prevRollDes) / dt, -3.0, 3.0);
      prevPitchDes = pitchDes;
      prevRollDes = rollDes;

      // Lead-compensated attitude command
      let pitchCmd = pitchDes + 0.55 * (pitchDes - pitchHat) + 0.10 * dPitchDes - 0.03 * rPitchHat + 0.5 * attBiasPitch;
      let rollCmd = rollDes + 0.55 * (rollDes - rollHat) + 0.10 * dRollDes - 0.03 * rRollHat + 0.5 * attBiasRoll;

      // Near floor during landing, limit tilt so we never exceed landingTilt*2 (0.36 rad)
      if (obs.gateIndex === 3 && py < 0.16) {
        const maxTilt = py < 0.105 ? 0.15 : 0.26;
        pitchCmd = clamp(pitchCmd, -maxTilt, maxTilt);
        rollCmd = clamp(rollCmd, -maxTilt, maxTilt);
      } else {
        pitchCmd = clamp(pitchCmd, -0.58, 0.58);
        rollCmd = clamp(rollCmd, -0.58, 0.58);
      }

      const cosTilt = Math.max(0.55, Math.cos(rollHat) * Math.cos(pitchHat));
      const thrustCmd = clamp(fTy / (kThrust * cosTilt), 0.05, 1.0);

      yawInt = clamp(yawInt + yawHat * dt, -0.4, 0.4);
      const yawRateCmd = clamp(-1.8 * yawHat - 0.8 * yawInt, -1.0, 1.0);

      prevAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      return prevAction;
    },
  };
}

